class GameResult
{
    public string GameName { get; set; }
    public int Score { get; set; }

    public GameResult(string gameName, int score)
    {
        GameName = gameName;
        Score = score;
    }
}

// The climb in progress, shared by every form (chapter 8)
static class Expedition
{
    public static Player CurrentPlayer;   // who is logged in

    // The eight summits, their heights and their games, in place order
    public static string[] Summits = { "Slieve Binnian", "Slieve Lamagan",
        "Slieve Meelmore", "Slieve Commedagh", "Slieve Bearnagh",
        "Chimney Rock Mountain", "Slieve Muck", "Slieve Donard" };
    public static int[] Heights = { 746, 702, 680, 767, 739, 656, 670,
        850 };
    public static string[] Games = { "Pack the Rucksack", "Knot Pairs",
        "Leave No Trace", "Read the Sky", "Whiteout", "Grid Ref Rescue",
        "Route Timer", "Listen Out" };

    public static bool[] Done = new bool[8];
    public static GameResult[] Results = new GameResult[8];

// Starts a new climb: nothing done, no results
public static void Start(Player p)
{
    CurrentPlayer = p;
    for (int i = 0; i < 8; i++)
    {
        Done[i] = false;
        Results[i] = null;
    }
}

// Keeps the result of one game and ticks its summit
public static void Finish(int game, GameResult result)
{
    Results[game] = result;
    Done[game] = true;
}

// The points from every summit climbed so far
public static int Total()
{
    int total = 0;
    for (int i = 0; i < 8; i++)
    {
        if (Done[i]) total = total + Results[i].Score;
    }
    return total;
}

// How many summits have been climbed
public static int DoneCount()
{
    int count = 0;
    for (int i = 0; i < 8; i++)
    {
        if (Done[i]) count++;
    }
    return count;
}

// Where each summit's flag sits on the 600 by 600 map, in pixels
private int[] flagX = { 300, 354, 215, 456, 258, 564, 72, 522 };
private int[] flagY = { 516, 360, 199, 204, 234, 378, 420, 264 };
private string[] photoNames = { "summit-binnian.jpg",
    "summit-lamagan.jpg", "summit-meelmore.jpg",
    "summit-commedagh.jpg", "summit-bearnagh.jpg",
    "summit-chimney-rock.jpg", "summit-muck.jpg",
    "summit-donard.jpg" };

private Button[] cards = new Button[8];
private PictureBox[] flags = new PictureBox[8];
private bool saved = false;    // true once the score is saved

// Puts the map, the cards and the flags on the screen
private void frmMap_Load(object sender, EventArgs e)
{
    ShowSpeaker();
    picMap.Image = Files.Picture("Map", "mournes-grid-600.png");
    for (int i = 0; i < 8; i++)
    {
        MakeCard(i);
        MakeFlag(i);
    }
    ShowProgress();
}

// One summit card down the right: photo, name, height and game
private void MakeCard(int i)
{
    Button card = new Button();
    card.Location = new Point(628, 64 + i * 62);
    card.Size = new Size(360, 58);
    card.FlatStyle = FlatStyle.Flat;
    card.FlatAppearance.BorderColor = Color.FromArgb(92, 107, 115);
    card.BackColor = Color.White;
    card.Font = new Font("Segoe UI", 10);
    card.TextAlign = ContentAlignment.MiddleLeft;
    card.ImageAlign = ContentAlignment.MiddleLeft;
    card.TextImageRelation = TextImageRelation.ImageBeforeText;
    card.Cursor = Cursors.Hand;
    Image photo = Files.Picture("Summits", photoNames[i]);
    if (photo != null) card.Image = new Bitmap(photo, new Size(72, 48));
    card.Tag = i;                  // the summit's place number
    card.Click += Summit_Click;
    cards[i] = card;
    this.Controls.Add(card);
}

// One flag on the map, on top of the summit
private void MakeFlag(int i)
{
    PictureBox flag = new PictureBox();
    flag.Size = new Size(32, 32);
    flag.SizeMode = PictureBoxSizeMode.Zoom;
    flag.BackColor = Color.Transparent;
    // so the see-through parts of the flag show the map
    flag.Parent = picMap;
    flag.Location = new Point(flagX[i] - 16, flagY[i] - 16);
    flag.Cursor = Cursors.Hand;
    flag.Tag = i;
    flag.Click += Summit_Click;
    flags[i] = flag;
}

// Shows the points so far, and which summits are climbed
private void ShowProgress()
{
    lblScore.Text = "Points so far: " + Expedition.Total()
        + " of 800";
    for (int i = 0; i < 8; i++)
    {
        string top = Expedition.Summits[i] + " · "
            + Expedition.Heights[i] + " m";
        if (Expedition.Done[i])
        {
            cards[i].Text = top + Environment.NewLine + "Climbed: "
                + Expedition.Results[i].Score + " points";
            cards[i].Enabled = false;
            cards[i].BackColor = Color.FromArgb(227, 241, 228);
            flags[i].Image = Files.Picture("Icons",
                "icon-check-64.png");
            flags[i].Cursor = Cursors.Default;
        }
        else
        {
            cards[i].Text = top + Environment.NewLine
                + Expedition.Games[i];
            flags[i].Image = Files.Picture("Icons",
                "icon-flag-64.png");
        }
    }
}

// A card or a flag was clicked: its Tag is the summit's number
private void Summit_Click(object sender, EventArgs e)
{
    Control clicked = (Control)sender;
    int i = (int)clicked.Tag;
    if (Expedition.Done[i]) return;   // climbed already
    OpenGame(i);
}

// Opens the game for summit i, then comes back to the map
private void OpenGame(int i)
{
    if (i == 7 && Sound.Muted)
    {
        DialogResult answer = MessageBox.Show("Listen Out needs "
            + "sound. Turn the sound on?", "Summit Ready",
            MessageBoxButtons.YesNo);
        if (answer == DialogResult.No) return;
        Sound.Muted = false;
        ShowSpeaker();
    }
    Form game = null;
    switch (i)
    {
        // each game chapter adds its own case below this line

    if (game == null) return;      // this game is not built yet
    this.Hide();
    game.ShowDialog();
    this.Show();
    ShowSpeaker();                 // the game may have changed it
    ShowProgress();
    if (Expedition.DoneCount() == 8)
    {
        MessageBox.Show("You have climbed all eight summits. Press "
            + "OK to see how you did.", "Summit Ready");
        OpenFeedback();
    }
}

// Finish the expedition: asks first if summits are left
private void btnFinish_Click(object sender, EventArgs e)
{
    int done = Expedition.DoneCount();
    if (done == 0)
    {
        MessageBox.Show("Climb at least one summit first. Click a "
            + "summit on the map to start.", "Summit Ready");
        return;
    }
    if (done < 8)
    {
        DialogResult answer = MessageBox.Show("You have climbed "
            + done + " of the 8 summits. Finish now? The summits "
            + "you have not climbed score 0.", "Summit Ready",
            MessageBoxButtons.YesNo);
        if (answer == DialogResult.No) return;
    }
    OpenFeedback();
}

// Shows the total for now (chapter 10 adds the feedback window)
private void OpenFeedback()
{
    MessageBox.Show("You scored " + Expedition.Total()
        + " out of 800 points.", "Summit Ready");
}

// Back to the welcome screen: closing the map runs FormClosing
private void btnBack_Click(object sender, EventArgs e)
{
    this.Close();
}

// Runs as the map closes, by Back or by the X
private void frmMap_FormClosing(object sender, FormClosingEventArgs e)
{
    if (saved || Expedition.DoneCount() == 0) return;
    DialogResult answer = MessageBox.Show("Leave the expedition? The "
        + "points from this climb will be lost.", "Summit Ready",
        MessageBoxButtons.YesNo);
    if (answer == DialogResult.No) e.Cancel = true;   // stay
}

// Shows the speaker picture that matches the sound being on or off
private void ShowSpeaker()
{
    string icon = "icon-speaker-on-64.png";
    if (Sound.Muted) icon = "icon-speaker-muted-64.png";
    picSound.Image = Files.Picture("Icons", icon);
}

// The speaker picture turns the sound off, or back on
private void picSound_Click(object sender, EventArgs e)
{
    Sound.Muted = !Sound.Muted;
    ShowSpeaker();
}

// Starts a new expedition on the map
private void btnStart_Click(object sender, EventArgs e)
{
    Expedition.Start(Expedition.CurrentPlayer);
    this.Hide();
    frmMap map = new frmMap();
    map.ShowDialog();              // waits until the map closes
    this.Show();
    ShowEverything();              // a new score shows at once
}

// Game, then Start the expedition
private void mnuStart_Click(object sender, EventArgs e)
{
    btnStart_Click(sender, e);
}

// The other way: one Next summit button, in place order
private int nextPlace = 0;

private void btnNext_Click(object sender, EventArgs e)
{
    OpenGame(nextPlace);
    if (Expedition.Done[nextPlace]) nextPlace = nextPlace + 1;
}
